import {
  ROLE_SHORTCUT_LIMITS,
  PLANS,
  PREVIEW_HIGHLIGHT_COMPARISON,
} from "./plans";

type ComparisonRow = readonly [
  label: string,
  free: string | number,
  premium: string | number,
];
export const PLAN_COMPARISON_ROWS: readonly ComparisonRow[] = [
  ["Monthly emails", PLANS.FREE.monthlyEmails, PLANS.PAID.monthlyEmails],
  ["Emails per UTC day", PLANS.FREE.dailyEmails, PLANS.PAID.dailyEmails],
  [
    "Recipients per campaign",
    PLANS.FREE.campaignRecipients,
    PLANS.PAID.campaignRecipients,
  ],
  [
    "Saved templates",
    `${PLANS.FREE.savedTemplates} editable/usable`,
    "Unlimited",
  ],
  ["PDF attachment", "One PDF, up to 5 MB", "One PDF, up to 5 MB"],
  ["Gmail acceptance status", "Included", "Included"],
  ["CSV import", "Unavailable", "Included; up to 1 MB/1,000 rows per import"],
  ["Contact job roles", "Any role", "Any role"],
  ["Edit recipient roles in Compose", "Unavailable", "Included"],
  [
    "Saved role shortcuts",
    `Up to ${ROLE_SHORTCUT_LIMITS.free} shortcuts`,
    `Up to ${ROLE_SHORTCUT_LIMITS.premium} shortcuts`,
  ],
  [
    "Re-add previously emailed contacts",
    "Enter and save details in Contacts",
    "Enter and save details in Contacts",
  ],
  ["Add to shortlist directly from History", "Unavailable", "Included"],
  [
    "Manual repeat sends",
    "Included; count toward allowances",
    "Included; count toward allowances",
  ],
  ["Mark replied button", "Unavailable", "Included"],
  [
    "Follow-up reminders",
    "Unavailable",
    `Choose ${PLANS.PAID.followUpDelayOptions.join(", ").replace(", 14", ", or 14")} days`,
  ],
  [
    "Themes",
    "Lavender and Nightbloom themes",
    "All four themes, including exclusive Chalk and Obsidian",
  ],
  [...PREVIEW_HIGHLIGHT_COMPARISON],
  ["Priority support", "Unavailable", "Prioritized email support"],
];

export const PLAN_CARD_FEATURES = {
  FREE: PLAN_COMPARISON_ROWS.map(([label, free]) => ({
    label,
    text: free === "Included" ? label : `${label}: ${free}`,
    included: free !== "Unavailable",
  })),
  PAID: PLAN_COMPARISON_ROWS.map(([label, , premium]) => ({
    label,
    text: premium === "Included" ? label : `${label}: ${premium}`,
    included: premium !== "Unavailable",
  })),
};

export const PLAN_FEATURES = {
  FREE: PLAN_CARD_FEATURES.FREE.map((feature) => feature.text),
  PAID: PLAN_CARD_FEATURES.PAID.map((feature) => feature.text),
};
